 CH_3NH_2\ +\ HBr \longrightarrow [CH_3NH_3]Br}\\[7pt]
 \mathrm{
 V(CH_3NH_2)\ =\ \Delta V\ =\ 2,24\ \text{л};}\\[1pt]
 \mathrm{
 n(CH_3NH_2)\ =\ \frac{V(CH_3NH_2)}{V_m}=}\\[1pt]
 \mathrm{
 =\ \frac{2,24\ \text{л}}{22,4\ \text{л/моль}}\ =\ 0,1\ \text{моль};
 } 
