 =\ \frac{1}{3}\ \cdotp\ 0,3\ \text{моль}\ =\ 0,1\ \text{моль}}\\[1pt]
 \mathrm{
 n(\text{суміші})\ =\ n(C_3H_8)\ +\ n(CH_3NH_2)\ =}\\[7pt]
